const FUNCS = 5000;
const OPS = 6;          // operations per function
const BC_PER_OP = 2;    // bytes of bytecode per op
const MC_PER_OP = 24;   // bytes of eager machine code per op

const totalOps = FUNCS * OPS;
const bytecodeKB = (totalOps * BC_PER_OP) / 1000;
const machineKB = (totalOps * MC_PER_OP) / 1000;
const savedPct = Math.round((1 - bytecodeKB / machineKB) * 100);

console.log('bytecode=' + bytecodeKB + 'KB machine=' + machineKB + 'KB saved=' + savedPct + '%');

tasks.starter:
function run(program, regs) {
  let acc = 0;
  for (const [op, n] of program) {
    if (op === 'Ldar') {
      acc = regs[n];          // load register n into accumulator
    } else if (op === 'Add') {
      // BUG: overwrites the accumulator with the register instead of
      // adding the register TO the accumulator.
      acc = regs[n];
    } else if (op === 'Return') {
      return acc;
    }
  }
  return acc;
}

tasks.verify:
const prog = [['Ldar', 0], ['Add', 1], ['Return']];
const r1 = run(prog, [2, 3]);
const r2 = run([['Ldar', 0], ['Add', 1], ['Add', 2], ['Return']], [10, 20, 30]);
const ok = r1 === 5 && r2 === 60;
console.log(ok ? 'PASS' : 'FAIL r1=' + r1 + ' r2=' + r2);
